import math

def pdf(x, m, s):
    return math.exp(-((x - m) ** 2) / (2 * s * s)) / (math.sqrt(2 * math.pi) * s)
print(round(0.30 * pdf(2, 2, 0.8), 4))
# prints: 0.1496

